const item = $input.first().json;

// ============================================================
// AEGIS ANALYST OUTPUT PARSER
// ============================================================

const raw =
  item.output ??
  item.text ??
  item.response ??
  "";

if (!raw) {
  throw new Error(
    "Sales AI Analyst returned no output."
  );
}

// ============================================================
// EXTRACT JSON FROM MODEL RESPONSE
// ============================================================

function extractJson(text) {

  let cleaned = String(text)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // ----------------------------------------------------------
  // 1. Try direct JSON
  // ----------------------------------------------------------

  try {
    return JSON.parse(cleaned);
  } catch {}

  // ----------------------------------------------------------
  // 2. Extract JSON object from surrounding text
  // ----------------------------------------------------------

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (
    start === -1 ||
    end === -1 ||
    end <= start
  ) {
    throw new Error(
      "Sales AI Analyst returned no JSON object."
    );
  }

  const candidate =
    cleaned.slice(start, end + 1);

  try {
    return JSON.parse(candidate);
  } catch (error) {
    throw new Error(
      "Sales AI Analyst returned invalid JSON: " +
      error.message
    );
  }
}

const parsed = extractJson(raw);

// ============================================================
// REQUIRED ANALYST FIELDS
// ============================================================

const requiredFields = [
  "observations",
  "evidence_analysis",
  "hypotheses",
  "missing_evidence",
  "next_steps",
  "overall_evidence_confidence"
];

for (const field of requiredFields) {

  if (!(field in parsed)) {
    throw new Error(
      `Sales AI Analyst output missing required field: ${field}`
    );
  }
}

// ============================================================
// NORMALIZE ARRAYS
// ============================================================

const arrayFields = [
  "observations",
  "evidence_analysis",
  "hypotheses",
  "missing_evidence",
  "next_steps"
];

for (const field of arrayFields) {

  if (!Array.isArray(parsed[field])) {
    throw new Error(
      `${field} must be an array.`
    );
  }
}

// ============================================================
// CONFIDENCE
// ============================================================

const confidence =
  Number(parsed.overall_evidence_confidence);

if (
  !Number.isFinite(confidence) ||
  confidence < 0 ||
  confidence > 1
) {
  throw new Error(
    "overall_evidence_confidence must be a number between 0 and 1."
  );
}

// ============================================================
// PRESERVE ANALYST STATE
// ============================================================

return [
  {
    json: {

      ...item,

      analyst: parsed,

      observations:
        parsed.observations,

      evidence_analysis:
        parsed.evidence_analysis,

      hypotheses:
        parsed.hypotheses,

      missing_evidence:
        parsed.missing_evidence,

      next_steps:
        parsed.next_steps,

      overall_evidence_confidence:
        confidence

    }
  }
];

// ============================================================
// AEGIS — Deterministic Evidence Metrics
// ============================================================

// Current input = output of Collect Sales Evidence
const current = $input.first().json;

// Original event = output of Generate Business Event
const generatedEvent = $("Generate Business Event").first().json;


// ============================================================
// Recursive field finder
// ============================================================

function findField(obj, targetKey, path = "") {
  if (obj === null || obj === undefined) {
    return null;
  }

  if (typeof obj !== "object") {
    return null;
  }

  if (Object.prototype.hasOwnProperty.call(obj, targetKey)) {
    return {
      value: obj[targetKey],
      path: path ? `${path}.${targetKey}` : targetKey
    };
  }

  for (const key of Object.keys(obj)) {
    const result = findField(
      obj[key],
      targetKey,
      path ? `${path}.${key}` : key
    );

    if (result !== null) {
      return result;
    }
  }

  return null;
}


function findRequired(obj, key, sourceName) {
  const result = findField(obj, key);

  if (!result) {
    throw new Error(
      `Could not find "${key}" in ${sourceName}.`
    );
  }

  return result;
}


// ============================================================
// Revenue comes from Generate Business Event
// ============================================================

const previousRevenueResult =
  findRequired(
    generatedEvent,
    "previous_revenue",
    "Generate Business Event"
  );

const currentRevenueResult =
  findRequired(
    generatedEvent,
    "current_revenue",
    "Generate Business Event"
  );


// ============================================================
// Payment/support evidence
//
// Search both:
// 1. Collect Sales Evidence
// 2. Generate Business Event
//
// This makes the node tolerant of our current data structure.
// ============================================================

function findFromSources(key, sources) {

  for (const source of sources) {

    const result = findField(
      source.object,
      key
    );

    if (result !== null) {
      return {
        ...result,
        source: source.name
      };
    }
  }

  throw new Error(
    `Could not find "${key}" in any available source.`
  );
}


const sources = [
  {
    name: "Collect Sales Evidence",
    object: current
  },
  {
    name: "Generate Business Event",
    object: generatedEvent
  }
];


const previousPaymentFailuresResult =
  findFromSources(
    "previous_failure_count",
    sources
  );

const currentPaymentFailuresResult =
  findFromSources(
    "current_failure_count",
    sources
  );

const previousPaymentTicketsResult =
  findFromSources(
    "previous_payment_tickets",
    sources
  );

const currentPaymentTicketsResult =
  findFromSources(
    "current_payment_tickets",
    sources
  );


// ============================================================
// Convert values to numbers
// ============================================================

const previousRevenue =
  Number(previousRevenueResult.value);

const currentRevenue =
  Number(currentRevenueResult.value);

const previousPaymentFailures =
  Number(previousPaymentFailuresResult.value);

const currentPaymentFailures =
  Number(currentPaymentFailuresResult.value);

const previousPaymentTickets =
  Number(previousPaymentTicketsResult.value);

const currentPaymentTickets =
  Number(currentPaymentTicketsResult.value);


// ============================================================
// Validate
// ============================================================

const values = {
  previousRevenue,
  currentRevenue,
  previousPaymentFailures,
  currentPaymentFailures,
  previousPaymentTickets,
  currentPaymentTickets
};

for (const [name, value] of Object.entries(values)) {

  if (!Number.isFinite(value)) {

    throw new Error(
      `${name} is not a valid number: ${value}`
    );

  }

}


// ============================================================
// Deterministic percentage calculation
// ============================================================

function percentageChange(previous, current) {

  if (previous === 0) {
    return null;
  }

  return Number(
    (
      ((current - previous) / previous) * 100
    ).toFixed(2)
  );

}


// ============================================================
// Calculate
// ============================================================

const revenueChange =
  percentageChange(
    previousRevenue,
    currentRevenue
  );

const paymentFailureChange =
  percentageChange(
    previousPaymentFailures,
    currentPaymentFailures
  );

const paymentTicketChange =
  percentageChange(
    previousPaymentTickets,
    currentPaymentTickets
  );


// ============================================================
// Return
// ============================================================

return [
  {
    json: {

      ...current,

      metrics: {

        revenue: {
          previous: previousRevenue,
          current: currentRevenue,
          percentage_change: revenueChange,

          direction:
            currentRevenue > previousRevenue
              ? "increased"
              : currentRevenue < previousRevenue
              ? "decreased"
              : "unchanged"
        },


        payment_failures: {
          previous: previousPaymentFailures,
          current: currentPaymentFailures,
          percentage_change: paymentFailureChange,

          direction:
            currentPaymentFailures > previousPaymentFailures
              ? "increased"
              : currentPaymentFailures < previousPaymentFailures
              ? "decreased"
              : "unchanged"
        },


        payment_tickets: {
          previous: previousPaymentTickets,
          current: currentPaymentTickets,
          percentage_change: paymentTicketChange,

          direction:
            currentPaymentTickets > previousPaymentTickets
              ? "increased"
              : currentPaymentTickets < previousPaymentTickets
              ? "decreased"
              : "unchanged"
        }

      },


      metric_sources: {

        previous_revenue:
          `Generate Business Event → ${previousRevenueResult.path}`,

        current_revenue:
          `Generate Business Event → ${currentRevenueResult.path}`,

        previous_payment_failures:
          `${previousPaymentFailuresResult.source} → ${previousPaymentFailuresResult.path}`,

        current_payment_failures:
          `${currentPaymentFailuresResult.source} → ${currentPaymentFailuresResult.path}`,

        previous_payment_tickets:
          `${previousPaymentTicketsResult.source} → ${previousPaymentTicketsResult.path}`,

        current_payment_tickets:
          `${currentPaymentTicketsResult.source} → ${currentPaymentTicketsResult.path}`

      },


      metrics_status: "calculated"

    }
  }
];

const item = $input.first().json;

const raw = item.output;

if (!raw || typeof raw !== 'string') {
  throw new Error('Aegis Critic returned no output.');
}

const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Critic response contains invalid JSON: ${error.message}`
  );
}

const requiredFields = [
  'critic_verdict',
  'analyst_score',
  'factual_errors',
  'numerical_errors',
  'unsupported_claims',
  'evidence_gaps',
  'hypothesis_assessment',
  'alternative_explanations',
  'required_corrections',
  'critic_confidence'
];

for (const field of requiredFields) {
  if (!(field in parsed)) {
    throw new Error(
      `Critic response is missing required field "${field}".`
    );
  }
}

if (!['pass', 'incomplete'].includes(parsed.critic_verdict)) {
  throw new Error(
    `Invalid critic_verdict: ${parsed.critic_verdict}`
  );
}

const arrayFields = [
  'factual_errors',
  'numerical_errors',
  'unsupported_claims',
  'evidence_gaps',
  'hypothesis_assessment',
  'alternative_explanations',
  'required_corrections'
];

for (const field of arrayFields) {
  if (!Array.isArray(parsed[field])) {
    throw new Error(
      `Critic field "${field}" must be an array.`
    );
  }
}

const analystScore = Number(parsed.analyst_score);
const criticConfidence = Number(parsed.critic_confidence);

if (
  !Number.isFinite(analystScore) ||
  analystScore < 0 ||
  analystScore > 1
) {
  throw new Error(
    'analyst_score must be a number between 0 and 1.'
  );
}

if (
  !Number.isFinite(criticConfidence) ||
  criticConfidence < 0 ||
  criticConfidence > 1
) {
  throw new Error(
    'critic_confidence must be a number between 0 and 1.'
  );
}

return [
  {
    json: {
      ...item,

      critic: parsed,

      critic_verdict: parsed.critic_verdict,
      analyst_score: analystScore,
      factual_errors: parsed.factual_errors,
      numerical_errors: parsed.numerical_errors,
      unsupported_claims: parsed.unsupported_claims,
      evidence_gaps: parsed.evidence_gaps,
      hypothesis_assessment: parsed.hypothesis_assessment,
      alternative_explanations: parsed.alternative_explanations,
      required_corrections: parsed.required_corrections,
      critic_confidence: criticConfidence
    }
  }
];

const item = $input.first().json;

// ============================================================
// AEGIS DECISION GATE
// Deterministic evaluation only.
// No loop control.
// ============================================================

const critic = item.critic;

if (!critic) {
  throw new Error(
    "Decision Gate: critic object not found."
  );
}

// ============================================================
// SCORES
// ============================================================

const analystScore =
  Number(critic.analyst_score ?? 0);

const criticConfidence =
  Number(critic.critic_confidence ?? 0);

// ============================================================
// CRITIC FINDINGS
// ============================================================

const factualErrors =
  Array.isArray(critic.factual_errors)
    ? critic.factual_errors.length
    : 0;

const numericalErrors =
  Array.isArray(critic.numerical_errors)
    ? critic.numerical_errors.length
    : 0;

const unsupportedClaims =
  Array.isArray(critic.unsupported_claims)
    ? critic.unsupported_claims.length
    : 0;

const requiredCorrections =
  Array.isArray(critic.required_corrections)
    ? critic.required_corrections.length
    : 0;

// ============================================================
// THRESHOLDS
// ============================================================

const minimumAnalystScore = 0.75;
const minimumCriticConfidence = 0.70;

// ============================================================
// PASS CONDITIONS
// ============================================================

const scorePass =
  analystScore >= minimumAnalystScore;

const confidencePass =
  criticConfidence >= minimumCriticConfidence;

const factualPass =
  factualErrors === 0;

const numericalPass =
  numericalErrors === 0;

const unsupportedPass =
  unsupportedClaims === 0;

const correctionsPass =
  requiredCorrections === 0;

// ============================================================
// FINAL DECISION
// ============================================================

const passed =
  scorePass &&
  confidencePass &&
  factualPass &&
  numericalPass &&
  unsupportedPass &&
  correctionsPass;

const status =
  passed
    ? "PASS"
    : "FAIL";

const route =
  passed
    ? "ACTION"
    : "REVIEW";

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      ...item,

      decision: {
        status,
        route,

        reasons: {
          scorePass,
          confidencePass,
          factualPass,
          numericalPass,
          unsupportedPass,
          correctionsPass
        },

        thresholds: {
          minimum_analyst_score:
            minimumAnalystScore,

          minimum_critic_confidence:
            minimumCriticConfidence
        }
      }
    }
  }
];

const item = $input.first().json;

// ------------------------------------------------------------
// CRITIC
// ------------------------------------------------------------

const critic = item.critic;

if (!critic) {
  throw new Error(
    "Build Critic Feedback: critic object not found."
  );
}

// ------------------------------------------------------------
// RECOVER THE ANALYST'S LATEST ANALYSIS
// ------------------------------------------------------------

// First try the incoming item.
let previousAnalysis = item.analysis ?? null;

// If Parse Critic Output dropped it, retrieve it directly
// from the latest Parse Analyst Output execution.
if (!previousAnalysis) {
  try {
    previousAnalysis = $('Parse Analyst Output').first().json.analysis;
  } catch (error) {
    throw new Error(
      "Build Critic Feedback: Could not retrieve the Analyst analysis from Parse Analyst Output."
    );
  }
}

if (!previousAnalysis) {
  throw new Error(
    "Build Critic Feedback: Analyst analysis is unavailable."
  );
}

// ------------------------------------------------------------
// BUILD FEEDBACK
// ------------------------------------------------------------

const feedback = {
  verdict: critic.critic_verdict ?? "unknown",

  analyst_score: Number(critic.analyst_score ?? 0),

  critic_confidence: Number(critic.critic_confidence ?? 0),

  factual_errors: Array.isArray(critic.factual_errors)
    ? critic.factual_errors
    : [],

  numerical_errors: Array.isArray(critic.numerical_errors)
    ? critic.numerical_errors
    : [],

  unsupported_claims: Array.isArray(critic.unsupported_claims)
    ? critic.unsupported_claims
    : [],

  evidence_gaps: Array.isArray(critic.evidence_gaps)
    ? critic.evidence_gaps
    : [],

  hypothesis_assessment: Array.isArray(critic.hypothesis_assessment)
    ? critic.hypothesis_assessment
    : [],

  alternative_explanations: Array.isArray(critic.alternative_explanations)
    ? critic.alternative_explanations
    : [],

  required_corrections: Array.isArray(critic.required_corrections)
    ? critic.required_corrections
    : []
};

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      ...item,

      previous_analysis: previousAnalysis,

      feedback,

      reanalysis_required: true
    }
  }
];

