const item = $input.first().json;

// ============================================================
// AEGIS ITERATION GUARD
// ============================================================

const currentIteration = Number(
  item.aegis_iteration ??
  item.iteration_control?.current_iteration ??
  0
);

const maxIterations = Number(
  item.max_iterations ??
  item.iteration_control?.max_iterations ??
  3
);

// ============================================================
// VALIDATION
// ============================================================

if (!Number.isFinite(currentIteration)) {
  throw new Error(
    "Aegis Iteration Guard: invalid current iteration."
  );
}

if (!Number.isFinite(maxIterations) || maxIterations < 1) {
  throw new Error(
    "Aegis Iteration Guard: invalid max_iterations."
  );
}

// ============================================================
// ROUTING DECISION
// ============================================================

const limitReached =
  currentIteration >= maxIterations;

const canReanalyze =
  !limitReached;

const route =
  limitReached
    ? "STOP"
    : "CONTINUE";

// ============================================================
// RETURN ONE STATE ITEM
// ============================================================

return [
  {
    json: {
      ...item,

      aegis_iteration: currentIteration,
      max_iterations: maxIterations,

      iteration_control: {
        current_iteration: currentIteration,
        max_iterations: maxIterations,
        can_reanalyze: canReanalyze,
        limit_reached: limitReached,
        route
      }
    }
  }
];

const item = $input.first().json;

// ============================================================
// AEGIS ITERATION STATE
// ============================================================

// Prefer the explicit Aegis iteration.
// Fall back to iteration_control.current_iteration if needed.
const currentIteration = Number(
  item.aegis_iteration ??
  item.iteration_control?.current_iteration ??
  0
);

const maxIterations = Number(
  item.max_iterations ??
  item.iteration_control?.max_iterations ??
  3
);

const nextIteration = currentIteration + 1;

// ============================================================
// SAFETY
// ============================================================

if (!Number.isFinite(currentIteration)) {
  throw new Error(
    "Increment Iteration: invalid current iteration."
  );
}

if (!Number.isFinite(maxIterations) || maxIterations < 1) {
  throw new Error(
    "Increment Iteration: invalid max_iterations."
  );
}

// ============================================================
// RETURN ONE STATE ITEM
// ============================================================

return [
  {
    json: {
      ...item,

      // Authoritative loop counter
      aegis_iteration: nextIteration,

      // Authoritative maximum
      max_iterations: maxIterations,

      // Explicit loop state
      iteration_control: {
        previous_iteration: currentIteration,
        current_iteration: nextIteration,
        max_iterations: maxIterations,
        can_reanalyze: nextIteration < maxIterations,
        limit_reached: nextIteration >= maxIterations,
        route:
          nextIteration >= maxIterations
            ? "STOP"
            : "CONTINUE"
      }
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      ...item,

      aegis_iteration: Number(item.aegis_iteration ?? 0),
      max_iterations: Number(item.max_iterations ?? 3)
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      ...item,

      investigation_context: {
        objective: "Determine the most plausible explanation for the detected anomaly.",

        evidence: item.evidence ?? item.metrics ?? item,

        investigation_domains: [
          "temporal",
          "payment",
          "system",
          "business"
        ],

        reasoning_rules: {
          correlation_is_not_causation: true,
          preserve_observed_facts: true,
          do_not_invent_evidence: true,
          explicitly_mark_missing_evidence: true
        }
      }
    }
  }
];

const items = $input.all();

const first = items[0]?.json ?? {};

return [
  {
    json: {
      ...first,

      investigation_results: items.map(item => item.json)
    }
  }
];

const item = $input.first().json;

// ============================================================
// AEGIS EVIDENCE OUTPUT PARSER
// Defensive parser for LLM-generated evidence synthesis.
// ============================================================

const raw =
  item.output ??
  item.text ??
  item.response ??
  "";

if (!raw) {
  throw new Error(
    "Evidence Synthesizer returned no output."
  );
}

// ============================================================
// JSON EXTRACTION
// ============================================================

function parseJson(text) {

  let cleaned = String(text)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // Remove common conversational prefixes/suffixes
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1 || end <= start) {
    throw new Error(
      "Evidence Synthesizer returned no JSON object."
    );
  }

  const candidate =
    cleaned.slice(start, end + 1);

  try {
    return JSON.parse(candidate);
  } catch (error) {
    throw new Error(
      "Evidence Synthesizer returned invalid JSON: " +
      error.message
    );
  }
}

const parsed = parseJson(raw);

// ============================================================
// REQUIRED TOP-LEVEL OBJECTS
// ============================================================

if (
  !parsed.evidence_map ||
  typeof parsed.evidence_map !== "object" ||
  Array.isArray(parsed.evidence_map)
) {
  throw new Error(
    "Evidence Synthesizer output must contain evidence_map as an object."
  );
}

// ============================================================
// NORMALIZE EVIDENCE MAP
// ============================================================

const domains = [
  "temporal",
  "payment",
  "system",
  "business"
];

const evidenceMap = {};

for (const domain of domains) {

  const value = parsed.evidence_map[domain];

  if (
    value === undefined ||
    value === null
  ) {
    evidenceMap[domain] = {};
  } else if (
    typeof value === "object" &&
    !Array.isArray(value)
  ) {
    evidenceMap[domain] = value;
  } else {
    evidenceMap[domain] = {
      raw_value: value
    };
  }
}

// ============================================================
// NORMALIZE ARRAY FIELDS
// ============================================================

function normalizeArray(value, fieldName) {

  if (value === undefined || value === null) {
    return [];
  }

  if (Array.isArray(value)) {
    return value;
  }

  // If the model returned one object instead of an array,
  // preserve it rather than failing the entire investigation.
  if (typeof value === "object") {
    return [value];
  }

  // If the model returned a string, preserve it as one item.
  if (typeof value === "string") {
    return [value];
  }

  throw new Error(
    `${fieldName} has an unsupported output type.`
  );
}

const convergingEvidence =
  normalizeArray(
    parsed.converging_evidence,
    "converging_evidence"
  );

const conflictingEvidence =
  normalizeArray(
    parsed.conflicting_evidence,
    "conflicting_evidence"
  );

const missingEvidence =
  normalizeArray(
    parsed.missing_evidence,
    "missing_evidence"
  );

// ============================================================
// CANDIDATE RELATIONSHIPS
// ============================================================

// Accept the intended field.
// Also support the alternate field the model has produced
// in previous runs.

let candidateRelationships;

if (
  parsed.candidate_relationships !== undefined
) {

  candidateRelationships =
    normalizeArray(
      parsed.candidate_relationships,
      "candidate_relationships"
    );

} else if (
  parsed.possible_relationships !== undefined
) {

  candidateRelationships =
    normalizeArray(
      parsed.possible_relationships,
      "possible_relationships"
    );

} else {

  candidateRelationships = [];
}

// ============================================================
// CONFIDENCE
// ============================================================

let confidence =
  Number(parsed.overall_evidence_confidence);

if (!Number.isFinite(confidence)) {

  // Some previous model outputs used "confidence"
  // instead of the requested field.
  confidence =
    Number(parsed.confidence);
}

if (!Number.isFinite(confidence)) {
  confidence = 0;
}

confidence =
  Math.max(
    0,
    Math.min(1, confidence)
  );

// ============================================================
// PRESERVE COMPLETE SYNTHESIS
// ============================================================

const normalizedSynthesis = {
  ...parsed,

  evidence_map:
    evidenceMap,

  converging_evidence:
    convergingEvidence,

  conflicting_evidence:
    conflictingEvidence,

  missing_evidence:
    missingEvidence,

  candidate_relationships:
    candidateRelationships,

  overall_evidence_confidence:
    confidence
};

// ============================================================
// RETURN AEGIS STATE
// ============================================================

return [
  {
    json: {

      ...item,

      evidence_map:
        evidenceMap,

      converging_evidence:
        convergingEvidence,

      conflicting_evidence:
        conflictingEvidence,

      missing_evidence:
        missingEvidence,

      candidate_relationships:
        candidateRelationships,

      overall_evidence_confidence:
        confidence,

      evidence_synthesis:
        normalizedSynthesis

    }
  }
];

const item = $input.first().json;

// ============================================================
// AEGIS FINAL INVESTIGATION REPORT
// Deterministic report assembly.
// No LLM reasoning.
// ============================================================

const decision = item.decision ?? {};
const analyst = item.analyst ?? {};
const critic = item.critic ?? {};
const evidence = item.evidence_synthesis ?? {};

// ============================================================
// STATUS
// ============================================================

const status =
  decision.status ?? "INCONCLUSIVE";

// ============================================================
// ANOMALY SUMMARY
// ============================================================

let anomalySummary = "";

if (analyst.observations?.length) {
  anomalySummary =
    analyst.observations.slice(0, 3).join(" ");
}

if (!anomalySummary) {
  anomalySummary =
    "Aegis detected an anomaly but the available investigation data is insufficient for a complete summary.";
}

// ============================================================
// ESTABLISHED FACTS
// ============================================================

const establishedFacts = [
  ...(Array.isArray(analyst.observations)
    ? analyst.observations
    : [])
];

// ============================================================
// EVIDENCE SUMMARY
// ============================================================

const evidenceSummary = [
  ...(Array.isArray(analyst.evidence_analysis)
    ? analyst.evidence_analysis
    : [])
];

// ============================================================
// HYPOTHESES
// ============================================================

const hypotheses = [
  ...(Array.isArray(analyst.hypotheses)
    ? analyst.hypotheses
    : [])
].map(hypothesis => ({
  hypothesis,
  status: "UNCONFIRMED"
}));

// ============================================================
// EVIDENCE GAPS
// ============================================================

const evidenceGaps = [
  ...(Array.isArray(critic.evidence_gaps)
    ? critic.evidence_gaps
    : []),

  ...(Array.isArray(analyst.missing_evidence)
    ? analyst.missing_evidence
    : [])
];

// Remove duplicates
const uniqueEvidenceGaps =
  [...new Set(
    evidenceGaps.map(String)
  )];

// ============================================================
// RECOMMENDED ACTIONS
// ============================================================

const recommendedActions = [
  ...(Array.isArray(analyst.next_steps)
    ? analyst.next_steps
    : []),

  ...(Array.isArray(critic.required_corrections)
    ? critic.required_corrections
    : [])
];

// Remove duplicate actions
const uniqueActions =
  [...new Set(
    recommendedActions.map(String)
  )];

// ============================================================
// CONFIDENCE
// ============================================================

const analystConfidence =
  Number(
    analyst.overall_evidence_confidence ?? 0
  );

const criticConfidence =
  Number(
    critic.critic_confidence ?? 0
  );

const finalConfidence =
  Math.max(
    0,
    Math.min(
      1,
      Math.min(
        analystConfidence,
        criticConfidence
      )
    )
  );

// ============================================================
// FINAL REPORT
// ============================================================

const finalInvestigation = {

  investigation_status:
    status,

  anomaly_summary:
    anomalySummary,

  established_facts:
    establishedFacts,

  evidence_summary:
    evidenceSummary,

  hypotheses:
    hypotheses,

  evidence_gaps:
    uniqueEvidenceGaps,

  recommended_actions:
    uniqueActions,

  confidence:
    finalConfidence
};

// ============================================================
// RETURN
// ============================================================

return [
  {
    json: {

      ...item,

      final_investigation:
        finalInvestigation,

      investigation_status:
        finalInvestigation.investigation_status,

      anomaly_summary:
        finalInvestigation.anomaly_summary,

      established_facts:
        finalInvestigation.established_facts,

      evidence_summary:
        finalInvestigation.evidence_summary,

      hypotheses:
        finalInvestigation.hypotheses,

      evidence_gaps:
        finalInvestigation.evidence_gaps,

      recommended_actions:
        finalInvestigation.recommended_actions,

      final_confidence:
        finalInvestigation.confidence

    }
  }
];
